@Override public void start(){
  EditionManagementState.PendingStatus status=editionManagementState.getPendingInstallationStatus();
switch (status) {
case NONE:    return;
case MANUAL_IN_PROGRESS:case AUTOMATIC_READY:  finalizeInstall(status);
break;
case AUTOMATIC_IN_PROGRESS:editionManagementState.installFailed("SonarQube was restarted before asynchronous installation of edition completed");
break;
case UNINSTALL_IN_PROGRESS:  try {
    failIfLicenseCommitIsPresent();
    editionManagementState.finalizeInstallation(null);
  } catch (IllegalStateException e) {
    editionManagementState.installFailed("License Manager plugin is still present after uninstallation of the edition. Please remove it.");
  }
  break;
default:throw new IllegalStateException("Unsupported status " + status);
}
}
